import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Flow, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for SetFlowVariables validation - empty values object
 * Should fail: Values object cannot be empty
 */
export const setFlowVariablesEmptyValues = Flow(
    {
        $id: Now.ID['set-flow-variables-empty-values'],
        name: 'SetFlowVariables Empty Values Test',
        description: 'Test SetFlowVariables validation with empty values object',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            status: StringColumn({
                label: 'Status',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set-flow-vars-empty-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // This should fail validation: empty values object
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-empty'],
                annotation: 'Invalid: empty values',
            },
            params.flowVariables,
            {} // Empty object - should fail
        )
    }
)
